window.K3_QRAW = window.K3_QRAW || [];
window.K3_QRAW.push.apply(window.K3_QRAW, [{"id": "edu-psych|xl-01|b9|34", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 34, "q": "儿童在某一时刻会觉得世界上所有的事物都是有生命的，不小心撞倒了椅子，会小心翼翼地把椅子扶起来，并且挨着椅子自言自语“不痛，不痛，伤口快好”，打碎了杯子，的儿童可能处于（）", "opts": ["感知运动阶段", "前运算阶段", "具体运算阶段", "形式运算阶段"], "a": 1, "exp": "题干中的儿童认为世界上所有的事物都是有生命的，思维具有泛灵性，说明这一阶段的儿童可能处于前运算阶段，故本题选B选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b9|35", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 35, "q": "亮亮第一次来到田野，非常兴奋，指着地里的麦苗叫韭菜。妈妈告诉他那是麦苗，并从手机里搜出韭菜和麦苗的图片，耐心地给他讲解了两者的不同，从这以后，亮亮学会了区分麦苗和韭菜。根据皮亚杰的认知发展理论，亮亮的认知图式发生了（）", "opts": ["同化", "迁移", "顺应", "成熟"], "a": 2, "exp": "本题考查的知识点是皮亚杰的建构主义发展观。皮亚杰认为个体在平衡与不平衡的交替中不断建构和完善认知结构，实现认知发展。心理结构涉及图式、同化、顺应和平衡等概念。顺应是指有机体不能利用原有图式接受和解释新刺激时，其认知结构发生改变来适应刺激的影响。题干中亮亮开始认为麦苗是韭菜，通过妈妈的讲解之后，能够区分麦苗和韭菜的不同，自身已有的认知结构发生了改变，体现了顺应，故答案选择C。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b9|36", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 36, "q": "丽丽看到奶奶不太高兴，她赶快从罐子里拿了自己最喜欢的巧克力给奶奶，她还说：“奶奶，我每次不高兴的时候，妈妈给我吃了巧克力我就高兴了，您吃了巧克力也会高兴的。”由此可见，丽丽的认知发展处在（）阶段", "opts": ["感知运动", "前运算", "具体运算", "形式运算"], "a": 1, "exp": "题干中的关键信息是丽丽“拿了自己最喜欢的巧克力给奶奶”，她认为自己吃了巧克力会高兴，奶奶吃了巧克力也会高兴，体现的是前运算阶段的儿童的思维具有自我中心的特点。故本题选B选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b9|37", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 37, "q": "根据皮亚杰的认知发展阶段理论，一般不可能出现在小学三年级学生身上的行为是）", "opts": ["能够进行假设命题，并验证假设", "能够从“A=B，B=C\"推出“A=C”", "在体育课上能够按老师说的“高矮顺序”自行列队", "知道两杯400mL的水即使放在不同大小的容器内，体积也是一样的"], "a": 0, "exp": "本题考查皮亚杰的认知发展阶段理论。A选项，能够进假设一演绎推理的儿童处于形式运算阶段（11岁之后），其思维已超越了对具体的可感知的事物的依赖。假设一演绎推理指个体的思维不仅能够运用经验一归纳的方式进行逻辑推理，而且能够运用假设一演绎推理方式来解决问题，这种行为一般不可能出现在小学三年级学生的身上。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b9|38", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 38, "q": "妈妈看到东东把皮球往墙上踢，便对他说：“墙壁爱干净，你把它的脸弄花了。”东东听了妈妈的话就不再把球往墙上踢，还用抹布一边擦墙壁一边说：“对不起，让我给你洗个脸吧。”以上现象说明东东的认知处于（）", "opts": ["具体运算阶段", "前运算阶段", "感知运动阶段", "形式运算阶段"], "a": 1, "exp": "在前运算阶段，儿童思维的特点有：①表象性思维；②“万物有灵论”，又称“泛灵论”，认为外界的一切事物都是有生命的；③一切以自我为中心（自我中心言语：重复、独白、集体独白）；④思维具有单向性、不可逆性；思维的集中化与刻板性；没有守恒概念。题干中，东东给墙壁洗脸，体现了“泛灵论”，说明东东的认知处于前运算阶段。因此B选项符合题意。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b11|39", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 39, "q": "【2007年311真题32】根据埃里克森的心理社会发展理论，小学儿童的主要发展任务是（）", "opts": ["获得自主感，克服羞怯感，体验意志的实现", "获得主动感，克服内疚感，体验目的的实现", "获得勤奋感，克服自卑感，体验能力的实现", "获得同一感，克服混乱感，体验忠诚的实现"], "a": 2, "exp": "本题属于对识记性知识的考查。根据埃里克森的心理社会发展理论，·第一章心理发展与教育社会化与人格发展理论与教育6~12岁儿童的主要发展任务是获得勤奋感，克服自卑感，体验能力的实现。本阶段儿童开始进人学校学习，面临来自家庭、学校以及同伴的各种要求和挑战，产生勤奋感。随着社交范围的扩大，儿童在不同社交活动中获得的经验以及完成任务和从事集体活动的成功经验，助长了儿童的胜任力(能力)，其中的困难和挫折则导致了自卑感。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b11|40", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 40, "q": "【2008年311真题31】埃里克森认为，青少年期人格发展的主要任务是获得（", "opts": ["勤奋感", "亲密感", "自我完善感", "自我同一感"], "a": 3, "exp": "/青少年时期指的是12~18岁，此阶段人格发展的主要任务是获得自我同响自我同一感的形成。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b11|41", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 41, "q": "【2020年311真题34】小星在家里很任性，上学后常与同桌为座位发生纠纷。根据布朗芬布伦纳的儿童心理发展生态系统理论，他在家中养成的习性对其在校与同学相处的影响，可归属于生态系统中的（）", "opts": ["微系统", "中系统", "外系统", "宏系统"], "a": 1, "exp": "中（间)系统指各微（观)系统之间的联系或相互关系。小星的家、学校对小星而言均属于微（观）系统，而在家的任性影响了在学校和同桌的相处，则属于微（观）系统之间的联系一中（间）系统。生态系统理论是由布朗芬布伦纳提出的关于个体发展模型的理论，分为四个层次，分别是微（观)系统、中（间)系统、外（层)系统和宏（观)系统。微（观）系统，指个体活动和交往的直接环境，它是环境层次的最里层。如学生的家庭和学校。中（间）系统，指各微（观）系统之间的联系或相互关系，如家庭和学校之间的相互影响。外（层）系统，指那些儿童并未直接参与但却对他们的发展产生影响的系统。如父母的工作环境。宏（观）系统，指存在于以上三个系统中的文化、亚文化和社会环境。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b11|42", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 42, "q": "【2021年311真题35】根据科尔伯格的道德发展阶段理论，学生最有可能出现创造性行为减少的阶段是（）", "opts": ["社会契约定向阶段", "遵守法规和秩序定向阶段", "相对功利定向阶段", "惩罚与服从定向阶段"], "a": 1, "exp": "在惩罚与服从定向阶段和相对功利定向阶段，个体没有什么创造性行为。在遵守法规和秩序定向阶段，个体的创造性行为会减少。到社会契约定向阶段，个体的创造性行为会增加。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b13|43", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 43, "q": "根据科尔伯格的道德发展阶段理论，学生认为“海因兹应该不应该偷药，要看他妻子平时对他好不好”，这表明此儿童的道德发展属于（", "opts": ["前习俗阶段", "准习俗阶段", "习俗阶段", "后习俗阶段"], "a": 0, "exp": "根据题意，儿童处于工具性相对主义的定向阶段，以个人的最大利益为出发点来考虑是否遵守规则。学生认为如果妻子对海因兹好就去偷药，不好就不去，这是典型的功利主义，属于前习俗阶段。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b13|44", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 44, "q": "若问小明“为什么偷东西是不对的？”他的回答是“抓住了会挨打”。据此可以判断小明的道德认知发展处于（", "opts": ["前习俗水平", "习俗水平", "后习俗水平", "准习俗水平"], "a": 0, "exp": "，小明不偷东西是为了避免挨打，属于避免惩罚，处于科尔伯格前习俗水平的第一阶段，即“服从和惩罚的定向阶段”。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b13|45", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 45, "q": "在海因兹偷药的问题中，认为海因兹应该去偷药，因为海因兹是为了救命才不得不去偷药，如果有什么需要改变的话，那应该是法律没有考虑到稀有药品应按照公平原则加以调控，法律才是需要修改的。这表明此儿童的道德认知属于（）", "opts": ["好孩子定向阶段", "维护法律权威和秩序定向阶段", "社会契约定向阶段", "工具性的相对主义定向阶段"], "a": 2, "exp": "处于社会契约阶段的儿童认识到规则是人为的、民主的、契约性的东西，当社会习俗或法律不符合公众利益时就应该修改。根据题意，儿童认为法律需要加以修改，这表明儿童的发展属于社会契约定向阶段。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b13|46", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 46, "q": "根据埃里克森的人格发展理论，三岁至六七岁儿童所要解决的主要矛盾有（", "opts": ["自主感对羞怯感", "主动感对内疚感", "勤奋感对自卑感", "自我同一性对角色混乱"], "a": 1, "exp": "三岁至六七岁的儿童属于学前期，面临的主要矛盾是主动感对内疚感。①2020年真题试卷中将微观系统、中间系统、外层系统、宏观系统表述为微系统、中系统、外系统、宏系统。的活动。成年人应该是监督而不是干涉儿童的主动性和创造性的活动。过多的干涉可能会造成儿童缺乏尝试和主动性缺失的性格选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b13|47", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 47, "q": "两三岁的儿童常常会要求自己独立完成一些任务，如吃饭、穿衣等，这时候家长应该给儿童提供这样的机会，即使他们失败了也不要责备，因为根据埃里克森的心理社会发展理论，这一阶段儿童的主要任务是形成（）", "opts": ["勤奋感", "自主感", "信任感", "角色同一性"], "a": 1, "exp": "本题考查的知识点是埃里克森的心理社会发展理论，根据埃里克森的心理社会发展理论，两三岁的儿童的主要冲突是自主对羞法。儿童在这一阶段的发展任务是培养自主感，故B选项正确。A选项，勤奋感是学龄期（6岁至12岁）儿童的主要发展任务。C选项，信任感是婴儿期(0~18个月左右)儿童的主要发展任务。D选项，角色同一性是青年期（12~18岁）儿童的主要发展任务。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b13|48", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 48, "q": "有的人对他人充满怀疑，对世界缺乏信任；有的人有很好的安全感，能够相信周围的人。根据埃里克森的发展理论，这更有可能是由于哪一阶段的发展差异造成的？（", "opts": ["婴儿期", "幼儿期", "儿童期", "青年期"], "a": 0, "exp": "本题考查对埃里克森的心理社会发展理论的理解。埃里克森认为婴儿期个体面临的发展任务是获得信任感，克服不信任感，体验希望的实现。如果在婴儿期没能获得对外部世界的信任感，将会对个体的心理发展产生消极影响，对世界缺乏信任。A选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b13|49", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 49, "q": ")发展阶段论，该生心理处于(", "opts": ["自主对羞愧", "信任对怀疑", "角色同一性对角色混乱", "勤奋对自卑"], "a": 2, "exp": "C选项，角色同一性对角色混乱（12~18岁）：这一阶段大体相当于少年期和青春初期。个体此时开始体会到自我概念问题的困扰，也即开始考虑“我是谁”这一问题，体验着角色同一与角色混乱的冲突。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b14|50", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 50, "q": "【2008年311真题33】兼具敏感、细心、情感体验深刻等积极品质和多疑、孤僻等消极ISS品质的气质类型是（", "opts": ["胆汁质", "多血质", "黏液质", "抑郁质"], "a": 3, "exp": "本题属于对识记性知识的考查。抑郁质的人敏感，细心，行为孤僻，不善交往，易多愁善感，反应迟缓，适应能力差，容易疲劳，性格具有明显的内倾性。不同的气质类型及特点：(1）多血质一活泼好动，反应迅速，热爱交际，能说会道，适应性强，但粗枝大叶，具有明显的外向倾向。（2）胆汁质一直率热情，精力旺盛，好冲动，但是暴躁易怒，脾气急，热情忽高忽低，喜欢新环境带来刺激的学习。(3）黏液质一安静、沉稳、踏实，反应性低，交际适度，自制力强，话少，适于从事细心、程序化的学习，表现出内倾性，可塑性差，有些死板，缺乏生气。(4）抑郁质一敏感，细心，行为孤僻，不善交往，易多愁善感，反应迟缓，适应能力差，容易疲劳，性格具有明显的内倾性。注意气质类型没有好坏之分。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b14|51", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 51, "q": "【2009年311真题36】下列各种个别差异中，不属于认知方式差异的是（", "opts": ["场依存型与场独立型", "冲动型与沉思型", "内控型与外控型", "分析型与综合型"], "a": 2, "exp": "认知方式包括场依存型和场独立型、冲动型和沉思型、分析型和综合型。C选项“内控型与外控型”属于归因方式，不是认知方式。，第一章心理发展与教育心理发展的差异与教育选项“编码系统”由加涅提出。它们都属于心理学概念，涉及个体的认知结构。只有C选项“学科基本结构”强调的不是认知结构，而是知识之间的基本结构。所谓学科基本结构，是指构成学科的基本概念、基本公式、基本原则、基本法则等，以及它们之间的相互联系与规律性。布鲁纳认为，学生理解了学科基本结构，就更容易掌握整个学科的具体内容。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b14|52", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 52, "q": "【2017年311真题34】学生根据已知信息、利用熟悉的规则解决问题的思维方式是(", "opts": ["直觉思维", "聚合思维", "抽象思维", "发散思维"], "a": 1, "exp": "聚合思维是学生根据已知信息、利用熟悉的规则解决问题的思维方式。A选项直觉思维是指基于直接感觉、经验和直觉形成的思维方式。它通常涉及情感、直觉式。它通常用符号和概念来表达和处理信息，而不依赖于感觉和经验。例如，当你在解决一个数学问题时，你需要运用符号和公式来推导。D选项发散思维表现为思维沿着不同的方向扩展，发散到各个有关方面。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b14|53", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 53, "q": "【2018年311真题37】“曹冲称象”反映了曹冲的（）", "opts": ["抽象思维", "聚合思维", "动作思维", "发散思维"], "a": 3, "exp": "用不同的方法解决同一问题属于发散思维。“曹冲称象”反映了曹冲的创新思维，属于发散思维。聚合思维表现为搜集或综合信息与知识，运用逻辑规律，缩小解答范围，直至找到最恰当的唯一正确的答案。发散思维表现为个人思维沿着不同的方向扩展，使观念发散到各个有关方面，最终产生多种可能的答案而不是唯一正确的答案，因而容易产生有创意的新颖观念。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b14|54", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 54, "q": "【2025年311真题38】智力的PASS模型主要包含计划、注意、同时性加工、继时性加工等认知加工过程，其中处于模型中最基础层次的是（）", "opts": ["计划", "注意", "同时性加工", "继时性加工"], "a": 1, "exp": "智力的PASS模型将认知过程分为三个层次，注意（又称注意-唤醒系统）处于最基础层次。它的核心功能是维持大脑唤醒状态、筛选关键信息，为更高层次的加工过程（同时性加工、继时性加工）和计划系统提供支持，没有注意的基础保障，其他认知过程无法有效开展。计划处于模型的最高层次，负责统筹、调控其他认知过程，并非基础层次。同时性加工和继时性加工属于中间层次，分别负责整合整体信息、按顺序处理序列信息，二者须依赖注意系统提供的信息筛选和唤醒知识，不属于基础层次。口", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b16|55", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 55, "q": "根据加德纳的多元智能理论，教育和评价要充分尊重、利用人的发展的（）", "opts": ["顺序性", "阶段性", "差异性", "不平衡性"], "a": 2, "exp": "加德纳的多元智能理论包括语言智能、逻辑一数学智能、空间智能、音乐智能、身体一运动智能、人际关系智能、自我认识智能。不同的人有不同的智能优势，加德纳强调的是人的智力的差异性。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-01|b16|56", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-01", "chName": "", "sec": "基础练习", "no": 56, "q": "课堂上，老师提问的话音未落，有的学生就急忙举手回答，但回答常常不够全面。这类学生所对应的认知加工方式为（", "opts": ["深层加工", "表层加工", "冲动型加工", "沉思型加工"], "a": 2, "exp": "本题考查的知识点是认知加工方式。根据认知的反应速度，认知加工方式可分为沉思型加工与冲动型加工；根据对学习内容的理解深度，认知加工方式可分为表层加工与深层加工。A选项深层加工强调对知识的理解，这类型的学生适合理解类的考查题目。B选项表层加工强调对知识的记忆，这类型的学生适合识记类知识的考查。度而非精度。D选项沉思型加工的个体在问题解决时常常不急于说出自己的看法，而是先对各种可能的答案进行分析，解决问题时往往强调精度而非速度。题干中的学生在回答问题的时候速度快而不够全面，符合冲动型认知方式的特征，故本题选C选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b19|1", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 1, "q": "【2007年311真题35】根据加涅对学习的分类，识别多种刺激的异同并对之做出不同的反应，这种学习是（）", "opts": ["连锁学习", "辨别学习", "概念学习", "规则学习"], "a": 1, "exp": "本题属于对识记性知识的考查。辨别学习能识别多种刺激的异同之处，并作出对应的反应。辨别学习有两种，单一辨别学习与多重辨别学习。加涅按照学习水平，把学习分为：（1）信号学习：这类学习属于经典性条件作用，个体学习对某种信号做出某种反应。这是最简单的一种学习，其先决条件是有机体先天的神经组织结构。(2）刺激一反应学习：指学习使一定的情境或刺激与一定的反应相结合，并得到加强，学会以某种反应获得某种结果。（3）连锁学习：指一系列刺激一反应的联合。（4）言语联想学习：由言语单位所联结的一系列刺激一反应的联合。(5）辨别学习：能识别多种刺激的异同之处，并做出对应的反应。（6）概念学习：在对刺激进行分类时，能识别它们之间的抽象特征，对同一类别的刺激做出相同的反应。（7）规则（或原理、法则）学习：指多种概念之间的联合。（8）解决问题学习：运用已学习过的规则或原理解决问题，以获得更高级的规则或原理。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b19|2", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 2, "q": "【2008年311真题41】按照加涅对学习结果的分类，下列选项中，不属于智慧技能的是(", "opts": ["言语信息", "具体概念", "定义概念", "问题解决"], "a": 0, "exp": "本题属于对识记性知识的考查。按照学习结果，加涅将学习分为了五类：言语信息的学习、智慧技能的学习、认知策略的学习、动作技能的学习、态度的学习。智慧技能按照由低到高依次是：辨别、概念、规则、高级规则。其中概念包括B选项的具体概念和C选项的定义概念。D选项问题解决属于高级规则。言语信息属于和智慧技能平行的层级，不属于智慧技能。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b19|3", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 3, "q": "【2009年311真题42】学生在了解了长方形面积公式、三角形面积公式及面积的可加性原则后，生成了梯形面积的计算公式。按照加涅的学习分类标准，这种学习属于（", "opts": ["辨别学习", "概念学习", "规则学习", "高级规则学习"], "a": 3, "exp": "高级规则学习也称为解决问题的学习，指运用已学习过的规则或原理来解决问题，以获得更高级的规则或原理。学生根据已有的规则“生成”新的计算公式，属于高级规则学习。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b19|4", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 4, "q": "【2010年311真题34】下列选项中，由学习引起的行为变化是（）", "opts": ["视觉适应", "望梅止渴", "青春期男孩变声", "服用兴奋剂提高成绩"], "a": 1, "exp": "学习是由练习所引I起的经验持久的变化。A、C、D选项都属于生理现象。B选项是由后天的经验引起的。如果一个人从来没有尝过梅子的味道，在他面前提“梅学习的概述子”，是不会分泌唾液的。对学习基本含义的科学理解，需要把握以下几点：第一，学习是一种经验的获得过程，在此过程中通过相应行为或态度的变化来体现；第二，学习需要学习者通过练习等方式获得，是学习者对环境的能动适应过程；第三，学习的实质是行为的持久改变，是学习者心理结构的质变、重建的过程。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b19|5", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 5, "q": "【2012年311真题34】根据加涅的学习层次分类观点，儿童学习游泳主要属于（", "opts": ["连锁学习", "信号学习", "规则或原理的学习", "解决问题的学习"], "a": 0, "exp": "儿童学习游泳属于一系列动作的结合，其实质是连锁学习。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b19|6", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 6, "q": "【2013年311真题36】下列尚未发生学习的现象是（）", "opts": ["杯弓蛇影", "蜜蜂采蜜", "望梅止渴", "老马识途"], "a": 1, "exp": "学习是通过练习所引起的经验持久的变化。“蜜蜂采蜜”是动物的本能活动，未发生学习的现象。“杯弓蛇影”是因为知道蛇的恐怖，才会害怕蛇。“望梅止渴”是因为尝过梅子的味道，才会一提起梅子，就分泌唾液。“老马识途”是因为马走过这段路后，才会记住。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b21|7", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 7, "q": "比概念学习的复杂程度高的是（", "opts": ["连锁学习", "信号学习", "辨别学习", "规则学习"], "a": 3, "exp": "本题考查的知识点是加涅的学习水平的分类。加涅根据学习的复杂程度，将学习分为了从低到高的8个层次，依次为信号学习、刺激一反应学习、连锁学习、言语联结学习、辨别学习、概念学习、规则学习或原理学习和解决问题学习。题目选项中复杂程度概念学习高的是规则学习，故选D选项", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b21|8", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 8, "q": "萌萌原来见了陌生人就躲避，上幼儿园一个月后，萌萌的这种行为消失了。根据加涅)学习的学习结果分类，这里发生的是（", "opts": ["言语信息", "态度", "智慧技能", "认知策略"], "a": 1, "exp": "本题考查学习的分类。态度学习指对人、事物及事件所采取的行动，包括对家庭、社会关系的认识，对某种活动产生的情感等。题干中萌萌的这种见了陌生人就躲的行为的消失属于态度学习。因此B选项正确。A选项，言语信息的学习即掌握以言语信息传递的内容，学习结果是以言语信息表现出来的，帮助学生解决“是什么”的问题。比如“北京是中国的首都”。C选项，智慧技能分为辨别、概念、规则、高级规则（解决问题）等，而辨别技能是最基本的智慧技能。智慧技能的学习帮助学生解决“怎么做”的问题，用以对外界的符号、信息进行处理加工。比如，怎样把分数转换为小数。D选项，认知策略是学习者用以支配他自己的注意、学习、记忆和思维的内在组织的才能，这种才能使得学习过程的执行控制成为可能。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b21|9", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 9, "q": "按照认知心理学的观点，机械学习与有意义学习划分的主要依据是（）", "opts": ["新旧知识间是否建立非人为的实质性联系", "学生是否主动学习、反复学习", "要学习的主要内容是教师呈现还是由学生发现", "学习的目的是解决问题还是获得知识"], "a": 0, "exp": "本题考查学习的分类。奥苏伯尔根据学习材料与学习者原有知识的关系，将学习分为机械学习和有意义学习。机械学习是指当前的学习没有与已有知识建立某种有意义的联系。有意义学习是指当前的学习与已有知识建立起实质性的、有意义的联系。由相关知识可知机械学习与有意义学习划分的主要依据是新旧知识间是否建立非人为的实质性联系。因此A选项正确。B选项、C选项以及D选项均不属于机械学习与有意义学习划分的主要依据，属于干扰项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b21|10", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 10, "q": "李教授参观一所中学时，翻了翻学生课桌上的课本，问道：“地下一千米比地面冷还是热？”学生面面相，默不作声。旁边的任课老师急了，马上问学生：“地球深层是什么地质结构？”全班学生马上回答：“是熔岩。”以上案例中，学生对地球结构的学习属于（", "opts": ["机械学习", "意义学习", "发现学习", "模仿学习"], "a": 0, "exp": "本题考查的知识点是臭苏伯尔关于学习的分类。奥苏伯尔依据学习材料与学习者原有知识的关系将学习分为机械学习和有意义学习。A选项，机械学习是指当前的学习没有与已有知识建立某种有意义的联系。题干中学生的表现说明他们只是记一·第二章学习及其理论解释口住了地球深层是熔岩这一信息，获得字面意思，并没有与其他信息建立起实质性的联系，属于机械学习。故本题选A选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b21|11", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 11, "q": "小林在中学实习两周后，学会了使用电子白板上课。根据加涅对学习结果的分类，小林的学习内容属于（）", "opts": ["智力技能", "认知策略", "言语信息", "运动技能"], "a": 0, "exp": "本题考查的知识点是加涅关于学习策略的分类。A选项，智力技能又称心智技能或智慧技能，智慧技能分为辨别、概念、规则、高级规则（解决问题）等，而辨别技能是最基本的智慧技能。智慧技能的学习帮助学生解决“怎么做”的问题，用以对外界的符号、信息进行处理加工。学习电子白板必须要理解电子白板的一些功能，比如擦除、剪切、复制等功能代表的意义和区别，涉及一些辨别和概念学习.而不是要仅靠练习就能学会的，需要动脑思考怎么做，因此属于智力技能的学习。能，这种才能使得学习过程的执行控制成为可能。认知策略与智力技能的不同在于智力技能指向学习者的外部环境，而认知策略支配着学习者在应对环境时其自身的行为，即“内在的”东西。材料中未涉及“学习方法”的问题，故排除B选项。C选项，言语信息的学习即掌握以言语信息传递的内容，学习结果是以言语信息表现出来的，帮助学生解决“是什么”的问题。比如“北京是中国的首都”。题干倾向的是“怎么做”，而不是“是什么”，故排除C选项。D选项，动作技能又称运动技能，如体操运动、写字技能，它也是能力的一个组成部分，更倾向的是怎么动手做，需要反复操作练习提高的技能。使用电子白板上课更多需要用脑去分析处理电子信息技术的问题，故排除D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b21|12", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 12, "q": "下列哪种学习属于有意义的接受学习（）", "opts": ["科学家探索新材料", "儿童尝试错误走迷宫", "小学生编打油诗背诵圆周率", "中学生听讲座，理解概念之间的关系"], "a": 3, "exp": "A选项，科学家探索新材料，是利用已有的知识点来发现，属于有意义的发现学习，不符合题意，A选项排除。B选项，儿童尝试错误走迷宫，没有知识之间的相互联系，属于一种机械的发现学习，不符合题意，B选项排除。C选项，小学生编打油诗背诵圆周率，是自己编造关联，属于人为建立的联系，不属于有意义的接受学习。D选项，听讲座是老师直接传递的，属于接受学习，其次学生还理解了概念之间的关系，属于有意义学习，故D选项为有意义的接受学习。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b21|13", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 13, "q": "妈妈给小童讲大灰狼的故事，大灰狼狡猾、凶残，假装兔妈妈闯进小白兔家里吃掉小白兔。故事讲了很多次以后，小童对大灰狼很讨厌。根据加涅对学习结果的分类，小童的学习属于（）", "opts": ["认识策略学习", "智慧技能学习", "态度学习", "言语信息学习"], "a": 2, "exp": "态度影响个体对人、事和物采取行动的内部状态。态度可以从各种学科的学习中得到，但更多的是从校内外活动和家庭中得到。题干中小童讨厌大灰狼体现了态度的学习。故C选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b21|14", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 14, "q": "“教学生学习任何科目，绝不是向学生灌输一些固定的知识，而是启发学生主动去求取)的观点知识与组织知识。”这是（", "opts": ["接受学习", "发现学习", "机械学习", "顿悟学习"], "a": 1, "exp": "发现学习是指学生在学习情境中通过自已的探索来获得问题答案的学习方式。布鲁纳认为，学习了解一般的原理原则固然重要，但尤其重要的是形成发现的态度和方法。学习者应该有一种探索新情境的态度，喜欢去做出假设、推测关系，发挥自己的能力去发现新事物，解决新问题。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b21|15", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 15, "q": "通过教学和训练，学生掌握了“行程问题”的解题方法，之后对于“行程问题”中的“相遇问题”“追赶问题”等都能很顺利地解决。根据加涅的学习分类，这一水平的学习属于(）", "opts": ["连锁学习", "概念学习", "规则学习", "问题解决学习"], "a": 3, "exp": "按学习水平分类，加涅提出了八类学习。①信号学习：学习对某种信号作出某种反应。经典性条件反射是一种信号学习。这是一种最简单的学习，其先决条件主要取决于有机体先天的神经组织。②刺激一反应学习：主要指操作性条件作用或工具性条件作用。其中强化在该类学习中起非常关键的作用。③连锁学习：是一系列刺激一反应的联合。个体首先要习得每个刺激一反应联结，并口：照特定的顺序反复练习，同时还应接受必要的及时强化。④言语联想学习：其实质是连锁学习，只不过它是语言单位的连接，如将单词组合为合乎语法规则的句子。③辨别学习：能识别各种刺激特征的异同并做出相应的不同的反应。它既包括一些简单的辨别，如对不同形状、颜色的物体分别作出不同的反应，也包括复杂的多重辨别，如对相似的、易混淆的单词分别作出正确的反应。概念学习：对刺激进行分类，并对同类刺激作出相同的反应。这种反应是基于事物的某些特征而作出的，如圆的概念和质量的概念的学习。规则的学习：亦称原理学习，指了解概念之间的关系，学习概念间的联合。自然科学中的各种定律、定理的学习即是规则学习。8解决问题的学习：亦称高级规则的学习，指在各种条件下应用规则或规则的组合去解决问题。题干中能够解决“相遇问题”“追赶问题”等都属于问题解决的学习。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b23|16", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 16, "q": "【2007年311真题36】某小学生为了避免父母的斥责而认真完成家庭作业，其行为背。第二章学习及其理论解释后的作用机制是（）", "opts": ["正强化", "负强化", "正惩罚", "负惩罚"], "a": 1, "exp": "为了避免父母的斥责而认真完成家庭作业,属于避免不想要的刺激,为负强化。强化与惩罚的含义与示例：类型含义呈现愉快刺激，加强反应发正强化生频率消除厌恶刺激，加强反应发负强化生频率呈现厌恶刺激，减少反应发正惩罚生频率之后不再偷，努力学习撤销偷快刺激，减少反应发负惩罚生频率", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b23|17", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 17, "q": "【2007年311真题37】体现“身教重于言教”思想的学习理论派别是（", "opts": ["社会学习理论", "操作条件反射理论", "认知学习理论", "人本主义学习理论"], "a": 0, "exp": "题干“身教重于言教”突出的是榜样的力量，和班杜拉提出的社会学习理论有关。B选项“操作条件反射理论”和斯金纳有关，强调通过强化进行行为的塑造。C·第二章学习及其理论解释行为主义学习理论示例小明考得好后，父母奖励他，买了一双鞋给他。小明受到正强化，将来还会努力考好小明考得好后，父母不再让他参加他讨厌的补习班。小明受到负强化，将来还会努力考好小明偷没有好好学习，考试失败，父母打了小明。小明小明偷懒没有好好学习，考试失败，父母没收小明的零花钱。小明之后不再偷，努力学习杰斯有关，主张重视学生的情感等整体发展。观察学习是指人们通过观察他人（榜样）的行为及其结果学会某种复杂行为，又称替代学习、无尝试学习。班杜拉认为，人的一切社会行为都是在社会环境影响下，通过对他人的示范行为及其结果的观察学习而形成的。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b23|18", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 18, "q": "【2008年311真题38】在间歇强化的条件下，刺激一反应联结的特点是（", "opts": ["建立快，消退也快", "建立快，消退慢", "建立慢，消退快", "建立慢，消退也慢"], "a": 3, "exp": "强化程式分为连续强化和间歇强化。间歇强化包括定时强化、变时强化、定比强化和变比强化。间歇强化下，反应建立侵，消退也慢。连续强化下，反应建立快，消退也快。强化的类型：连续强化：给予每个反应强化，反应建立迅速，强化一旦终止，反应迅速消失。定时强化：存在扇贝效应，在时间间隔的末端反应率上升，表现突出，但持续性短，强化过去后反应速度迅速降低。变时强化：反应建立缓慢，行为建立后持续时间长。定比强化：反应建立迅速，强化后反应暂停，持续性较强。变比强化：反应建立速度快，强化后不会暂停，持续时间最长。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b23|19", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 19, "q": "【2009年311真题38】某生上课害怕被点名回答问题，当他发现坐在教室后排并趴在桌上时，就不大可能被提问，于是后来就越来越多地表现出类似行为。从行为主义的观点来看，这是由于该生曾受到（）", "opts": ["正强化", "负强化", "惩罚", "塑造"], "a": 1, "exp": "学生不想回答问题，发现坐在教室后排并趴在桌子上这一行为可以避免老师点名。老师不点名的行为是对学生坐在教室后排并趴在桌子上这一行为的负强化。这属于消除学生的厌恶刺激，促使学生趴在桌子上的频率越来越高。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b23|20", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 20, "q": "【2009年311真题45】一个经常违纪的学生被调到一个风气良好的班级后；在周围学生严格守纪行为的影响下，其违纪行为暂时很少表现出来。这体现了观察学习的（）", "opts": ["习得效应", "情绪唤起效应", "抑制效应", "社会促进效应"], "a": 2, "exp": "观察学习的效应包括习得效应、情绪唤起效应、抑制效应和社会促进效应。本题解题的关键在于“违纪行为暂时很少表现出来”，属抑制效应。抑制效应是指观种长期的行为改变。这种行为改变可能是暂时性的，也可能是持续性的。一个经常违纪的学生被调到风气良好的班级后，该学生在周围学生严格守纪行为的影响下，产生了对违纪行为的抑制效应，从而暂时减少了违纪行为的表现。A选项习得效应是指通过观察他人的行为并从中学习知识、技能、态度等的一种学习方式。B选项情绪唤起效应是指情绪状态（如愤怒、焦虑、兴奋等）对行为和思维的影响。情绪唤起可能会导致注意力、反应速度和判断偏见等方面的变化。题干没有体现。D选项社会促进效应是指当一个人在团体中时，他的表现能力会因为团体的支持或激励而得到提高。这个效应通常用于描述集体合作或竞争对于个体表现的影响。题于没有体现。观察学习的实质是人们可以通过观察他人的行为及行为的后果而间接地产生学习。行为的结果不影响新行为的习得，而影响新行为的表现。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b23|21", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 21, "q": "【2012年311真题36】同概念一样，规则也有正例、反例。下列表述能体现桑代克“效果律”正例的是(", "opts": ["“近朱者赤，近墨者黑”", "“得寸进尺”", "“人乡随俗”", "“吃小亏占大便宜”"], "a": 1, "exp": "桑代克认为试误学习成功的条件有三个：准备律、效果律、练习律。A、C选项属于环境的影响；D选项体现的是反例。准备律是指学习者在学习开始时的预备定式。练习律是指学习要经过反复的练习。效果律是指当建立了联结时，导致满意后果（奖励）的联结会得到加强，而带来惩罚的行为则会被削弱或淘汰。概念的正例和反例是指在一个概念范内，具有代表性和典型性的实例（正例），以及不属于该概念范的例子（反例）。通过引用正例和反例，可以帮助人们更好地理解和掌握某一概念的含义和范围。例如，在概念“动物”中，狗、猫、老虎、狮子等都是正例，因为它们是典型的动物，而植物、石头、机器等则是反例，因为它们不是动物。在学习和理解新概念时，通过引用正例和反例可以帮助我们更好地理解概念的内涵和外延，同时也可以避免对概念的误解和混淆。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b23|22", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 22, "q": "【2013年311真题38】某学生很怕猫。教师先让她看猫的照片，与她谈论猫，再让她看关在笼子中的猫，最后让她摸猫、抱猫，帮助她逐步消除对猫的恐惧反应。这种改变行为的方法属于（", "opts": ["行为塑造法", "系统脱敏法", "松弛训练法", "认知疗法"], "a": 1, "exp": "题干描述的是系统脱敏法的内容。系统脱敏法是按照刺激强度由弱到强、由小到大逐渐训练心理的承受力、忍耐力的方法。A选项行为塑造法是通过刺激反应来塑造个体行为的一种方式。C选项松弛训练法是一种压力缓解技巧，通过放松肌肉来减轻身体和心理的紧张状态。D选项认知疗法是一种心理治疗方法，旨在通过改变不健康的思维模式和信念来帮助人们解决不良情绪和行为问题，在认知疗法中，治疗师与患者一起分析惠者的思维方式，找出并挑战那些导致负面情绪和行为的错误信念和思维模式。通过学习新的合理的思维方式和技能，患者可以改变他们的态度和行为，从而改善他们的情绪状态和生活质量。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b23|23", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 23, "q": "【2014年311真题36】当儿童改正了不认真做作业的行为后，家长取消不准其看动画片的禁令。这种做法属于（", "opts": ["正强化", "负强化", "正惩罚", "负惩罚"], "a": 1, "exp": "负强化是避免了厌恶刺激，正惩罚是提供了厌恶刺激。儿童改正了不认真做作业的行为后，父母取消了厌恶刺激，属于消除厌恶刺激加强行为反应发生频率的做法，为负强化。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b23|24", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 24, "q": "【2015年311真题37】研究表明，学习成功的学生往往对学习抱积极态度，而屡受挫折的学生易对学习抱消极态度。能对这种现象做出合理解释的是（）", "opts": ["认知失调理论", "社会学习理论", "效果律", "准备律"], "a": 2, "exp": "题目涉及的是桑代克的效果律。效果律即情境与反应的联结因获得积极的结果而增强，因获得消极的结果而减弱。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b23|25", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 25, "q": "【2021年311真题34】“风声鹤唤，草木皆兵”反映的是条件作用的（）", "opts": ["强化", "泛化", "消退", "分化"], "a": 1, "exp": "“风声鹤唳，草木皆兵”是指听到风声和鹤鸣声，都疑心是追兵，把草和树木都当作了敌人的兵将。属于条件作用的泛化概念定义通过给予奖励或惩罚，增加某一行强化为发生的概率将一个条件反应在不同的情境或泛化刺激下推广或扩散到其他类似刺激上某一行为或条件反应逐渐消失或消退减弱将不同的刺激或条件区分开，以便分化区分何时应该做出不同的反应", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b25|26", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 26, "q": "将强化分为直接强化、替代强化和自我强化的心理学家是", "opts": ["班杜拉", "马斯洛", "韦纳", "阿特金森"], "a": 0, "exp": "班杜拉将强化分为的直接强化、替代强化和自我强化。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b25|27", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 27, "q": "小孩多次通过哭闹获得玩具，为矫正这种行为、父母不予理睬。这体现了行为主义中的()原理", "opts": ["惩罚", "强化", "负强化", "消退"], "a": 3, "exp": "消退指的是对不希望强化的行为不进行强化，符合题干现象。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b25|28", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 28, "q": "小明在商场哭闹，想要玩具赛车、妈妈没有理他的哭闹。关于妈妈的做法，说法错误的是(", "opts": ["妈妈的做法采用了行为主义的原理", "妈妈避免了对小明错误行为的强化", "妈妈利用了消退的原理", "妈妈的做法对小明是一种负强化"], "a": 3, "exp": "负强化指的是通过撤销厌恶刺激，加强反应发生频率，题干中是消退的原理，符合行为主义、避免了对错误行为的强化。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b25|29", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 29, "q": "每次上新课前，老师都会预设问题激发学生思考，并让学生预习，这符合桑代克“学习定律”中的（）", "opts": ["效果律", "准备律", "练习律", "学习律"], "a": 1, "exp": "本题考查的知识点是桑代克的试误说。桑代克的试误说有三个重要的学习定律，分别是准备律、效果律、练习律。其中准备律是指在进人某种学习活动之前，如果学习者做好了与相应的学习活动相关的预备性反应（包括生理的和心理的），学习者就能比较自如地掌握学习的内容。题干中的提前预习，正符合准备律的定义，故本题选B选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b25|30", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 30, "q": "以下不属于联结学习理论的观点的是（", "opts": ["学习的实质是形成刺激与反应的联结", "联结需要通过试误而建立", "原有知识结构对学习十分重要", "学习的成效影响后继学习"], "a": 2, "exp": "本题考查的知识点是学习理论。认知派的学习理论认为学习不是在外部环境的支配下被动地形成S一R联结，而是主动地在头脑内部构建认知结构；学习不是通过练习与强化形成反应习惯，而是通过顿语与理解获得期待；当有机体当前的学习依赖于他原有的认知结构和当前的刺激情境时，学习受主体的预期所引导，而不是受习惯所支配。C选项“原有知识结构对学习十分重要”，属于认知学习理论的观点，不属于联结学习理论的观点，故本题选C选项。A选项，桑代克的试误说认为学习的过程是刺激与反应之间建立联结的过程。B选项，桑代克认为联结是通过盲目尝试，逐步减少错误（试误）而形成的，因此他把自己的观点又称为试误说。D选项，桑代克的效果律认为奖惩对联结效果有重要影响，奖励则联结增强，惩罚则联结削弱。因此，他认为学习的成效影响着后继学习。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b26|31", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 31, "q": "狗最初对圆形和椭圆形做出同样的反应，经训练后仅对圆形做出该反应，这都是条件反射的（）", "opts": ["获得", "消退", "泛化", "分化"], "a": 3, "exp": "本题考查巴甫洛夫的经典性条件作用理论。刺激分化指的是通过选择性强化和消退使有机体学会对条件刺激和与条件刺激相类似的刺激做出不同的反应。题干中狗对圆形和椭圆形产生不同的反应，就是分化的过程，故本题选D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b26|32", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 32, "q": "某学生做了一件好事，老师在全班同学面前表扬他。该老师运用的是（）", "opts": ["潜伏学习理论", "模仿学习理论", "建构学习理论", "观察学习理论"], "a": 3, "exp": "本题考查班杜拉的观察学习理论。D选项，班杜拉认为由直接经验导致的所有学习现象，都可以在替代的基础上发生，即都可以通过观察他人行为及其结果而实现。观察学习，又称替代学习，是指通过对他人及其强化性结果的观察，一个人获得某些新的反应，或者矫正原有的行为反应，而在这一过程中，学习者作为观察者并没有外显的操作。老师在全班同学面前表扬做好事的学生，是为了让全班同学了解到做好事可以获得表扬，从而强化全班同学做好事的行为，在这个过程中全班同学作为观察者并没有外显的操作，这体现了班杜拉的观察学习理论。故本题选D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b26|33", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 33, "q": "得出学习即强化的观点的实验是（", "opts": ["经典条件反射实验", "操作条件反射实验", "榜样学习实验", "问题表征"], "a": 1, "exp": "本题考查的知识点是操作条件反射实验。斯金纳认为，人和动物的行为有两种：应答性行为和操作性行为。应答性行为是由特定刺激所引起的，是经典条件作用的研究对象。而操作性行为则不与任何特定刺激相联系，是有机体自发作出的随意反，第二章，学习及其理论解释应，是操作性条件作用的研究对象。操作性行为主要受强化规律的制约。所以，得出学习即强化的观点的实验是操作条件反射实验。A选项，经典条件反射实验得出学习是通过中性刺激与无条件刺激反复结合变成条件反应的过程的观点。C选项，榜样学习得出观察学习是人的学习的最重要的形式的观点。D选项，问题表征，也就是要理解问题的意思，澄清问题到底是什么。问题表征不是问题的客观描述或存在形式，而是学习者自己主动地“建构”起来的心理表征。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b26|34", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 34, "q": "小牧是小学二年级的学生，在学校里十分调皮，上课常常故意发出一些奇怪的声响引起其他同学的注意，每次老师都要对其严厉制止，为此打断课程，这让许多老师十分头疼。为了改变小牧这一行为，班主任和其他几位任课老师商量，决定以后小牧每次发出奇怪声响时，老师都继续上课不予理，慢慢地小牧也就不再发出声响了。这一案例中班主任采用的方法属于（）", "opts": ["正强化", "负强化", "消退", "惩罚"], "a": 2, "exp": "本题考查的知识点是操作性条件作用理论。C选项，消退是一种无强化的过程，有机体做出以前曾被强化过的反应，如果在这一反应之后不再有强化物相伴，那么，此类反应在将来发生的概率便降低。对学生不理是常用的一种消退方式。故C选项正确。A选项，正强化指给予一个愉快刺激，从而增强其行为出现的概率。B选项，负强化指摆脱一个厌恶刺激，从而增强其行为出现的概率。D选项，惩罚指当有机体做出某种反应以后，呈现一个厌恶刺激（如体罚、遭责等），以消除或抑制此类反应的过程。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b26|35", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 35, "q": "小芳的妈妈乐于助人，受其影响小芳在学校也常常关心帮助同学。小芳的学习属于）", "opts": ["试误学习", "顿悟学习", "强化学习", "观察学习"], "a": 3, "exp": "，本题考查的知识点是观察学习。观察学习又称为替代学习，是指通过对他人及其强化性结果的观察，一个人获得某些新的反应，或者矫正原有的行为反应。小芳通过观察妈妈而学习到了乐于助人的行为，属于观察学习。故D选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b26|36", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 36, "q": "以下不属于班杜拉对学生行为强化的方式的是（", "opts": ["直接强化", "替代强化", "自我强化", "榜样强化"], "a": 3, "exp": "本题考查的知识点是班杜拉的强化分类。班杜拉把强化分为直接强化、替代性强化和自我强化。A选项，直接强化是观察者因表现出观察行为而受到强化。B选项，替代强化是观察者因看到榜样的行为被强化而受到强化。C选项，自我强化是人能观察自己的行为，并根据自己的标准进行判断，由此强化或处罚自己。A、B、C选项均属于班杜拉对学生行为强化的方式。D选项，榜样强化不属于班杜拉对学生行为强化的方式。故本题选D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b26|37", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 37, "q": "快下课了，学生们开始躁动，这时候老师说：“如果大家认真听课，我就不安排额外的作业。”学生们顿时安静下来。该老师的做法属于（", "opts": ["正强化", "负强化", "惩罚", "消退"], "a": 1, "exp": "本题考查的知识点是斯金纳的强化原理。B选项，负强化强调摆脱厌恶刺激，增加行为发生的频率。题干教师通过撤销额外作业这一厌恶刺激从而增加学生认真听课的反应，属于负强化。A选项，正强化强调给予一个偷快刺激，增加行为发生的频率。C选项，惩罚强调呈现一个厌恶刺激从而减少行为发生的频率。D选项，消退是指有机体做出以前曾被强化过的反应，如果在这一反应之后不再有强化物相伴，那么，此类反应在将来发生的频率便降低。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b26|38", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 38, "q": "班杜拉社会学习理论中总结的学习过程的四个基本环节是（）", "opts": ["注意—保持——复制——动机", "注意—模仿—保持——动机", "注意——练习—保持—再现", "注意—模仿—练习——再现"], "a": 0, "exp": "本题为对识记性知识的考查，A选项是班杜拉社会学习理论关于学习过程的四个基本环节的正确表述。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b26|39", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 39, "q": "为了增强学生学习的投人度，教师在课程中不定期安插随堂小测验，这种强化程序属于（）", "opts": ["变时强化", "变比强化", "定时强化", "定比强化"], "a": 0, "exp": "本题考查的知识点是操作性条件反射作用理论中的强化程式。强化程式是指反应受到强化的时机和频次。强化程式可分为连续强化程式和间隔强化程式。间隔强化程式根据时间和比率、固定和可变两个维度组合出四种强化程式：A选项，变时强化是指强化的时间间隔是不固定的。B选项，变比强化是指强化和反应次数之间的比例是变化的。C选项，定时强化是指强化的时间间隔是固定的。D选项，定比强化是指强化和反应次数之间呈现一定的比例。题干中教师不定期安插随堂小测验，表明其进行强化时的时间间隔是不固定的，属于变时强化，故本题选A选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b26|40", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 40, "q": "陈老师在教学过程中十分注重对学生的学习进行反馈：学生做得好时，予以表扬；做得不好时，及时指出使其改正。陈老师的做法体现了桑代克学习理论中的（）", "opts": ["效果律", "练习律", "准备律", "应用律"], "a": 0, "exp": "本题考查的知识点是桑代克的尝试一错误学习的基本规律。桑代克认为学习有三条主要定律，即准备律、练习律、效果律。因此排除D。A选项的效果律是指学习者在学习过程中所得到的各种正或负的反馈意见会加强或减弱学习者在头脑中已经形成的某种联结。效果律是最重要的学习定律。B选项的练习律是指对于学习者已形成的某种联结，在实践中正确地重复这种反应会有效地增强这种联结。C选项的准备律是指在进人某种学习活动之前，如果学习者做好了与相应的学习活动相关的预备性反应（包括生理的和心理的），学习者就能比较自如地掌握学习的内容。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b26|41", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 41, "q": "李老师答应冯佳，如果她能在课堂上积极发言就消除她之前的违纪记录。这属于（", "opts": ["替代性强化", "自我强化", "正强化", "负强化"], "a": 3, "exp": "负强化是指个体在做出某种反应之后，令其摆脱厌恶刺激（撤销惩罚），从而提高其类似行为出现的概率。题干中李老师以消除违纪记录来强化学生积极发言的行为，属于负强化。故本题选D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b28|42", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 42, "q": "【2008年311真题42】学生在理解“力”概念的基础上，再来学习“重力”的概念。这种学习属于（", "opts": ["派生类属学习", "相关类属学习", "并列结合学习", "总括学习"], "a": 0, "exp": "例证,或是能从已有命题中直接派生出来的。学生在理解“力”的概念的基础上,再来学习“重力”的概念，这种学习属于派生类属学习。常见的学习类型：定义学习类型新的学习内容仅仅是学生已有的、包容面较广派生类属学习的命题的一个例证，或是能从已有命题中直接派生出来的相关类属学习新学的知识修订原有知识同时学习两个或多个类别的信息，以便将它们并列结合学习一起记忆和理解学习某个主题或领域中所有相关的信息，并将总括学习它们组合起来以形成一个全面的理解·第二章学习及其理论解释学习的认知理论代表人物布鲁纳奥苏伯尔托尔曼皮亚杰示例学生在理解“力”的概念的基础上，再来学习“重力”的概念一开始认为会飞的是鸟，鸟有羽毛。后来知道企鹅是鸟同时学习数学和科学学习历史的大事件，以便理解这些事件是如何影响某个国家发展的", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b28|43", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 43, "q": "【2015年311真题38】在上“圆柱体体积计算”这节课时，老师要求学生通过实验来确定如何测量体积。教师所采取的教学策略是（）", "opts": ["接受学习", "操作性条件学习", "发现学习", "观察学习"], "a": 2, "exp": "教师要求学生通过实验测量圆柱体体积，属于发现学习。如果教师直接给学生讲授圆柱体体积的计算方法，属于接受学习。接受学习、操作性条件学习、发现学习和观察学习的定义及示例：学习类型定义学习者被动地接受信息、观念或技能，最常见于接受学习传统的教学方法操作性条件学习行为和结果之间的联系并形成条件反射学习学习者通过实验、探究和自我寻找发现问题的发现学习解决方案观察学习学习者观察和模仿其他人的行为和结果", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b28|44", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 44, "q": "【2021年311真题36】无论是文字配上插图，还是图片配上文字，都有助于学习者回）忆相关的内容。从信息加工角度看，这主要是因为（", "opts": ["形成了信息组块", "使用了双重编码", "扩展了工作记忆容量", "进行了有意义编码"], "a": 1, "exp": "正确答案是B选项使用了双重编码。双重编码是指将信息以两种或多种方式表示和加工，以便更容易地将其存储在记忆中。例如，将文字与图片或图表结合使用，将会激活两个不同的信息加工过程：一个是通过看到图片或图表形成的视觉图像信息加工，另一个是通过阅读文字形成的语义信息加工。A选项中的信息组块是指将单个的信息综合起来，形成一个新的、更大的信息单位，以便更容易存储在工作记忆或长期记忆中。C选项中的工作记忆是指短期内存储和处理信息的能力。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b28|45", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 45, "q": "【2024年311真题35】根据奥苏伯尔的学习分类，生物学家在科学研究过程中向统计学家请教数据分析方法，这种学习属于（", "opts": ["有意义的接受学习", "机械的接受学习", "有意义的发现学习", "机械的发现学习"], "a": 0, "exp": "生物学家向统计学家直接请教，而不是自己发现，体现的是接受学习。题法，而不是死记硬背类的机械学习，属于有意义学习，故本题选A选项。二、分析论述题【参考答案】加涅根据学习的复杂程度将学习分成由低到高的八个层级：信号学习、刺激一反应学习、连锁学习、言语联想学习、辨别学习、概念学习、规则学习和解决向题学习。并指出低一层级的学习是其高一层级学习的前提和基础，学习具有层级性或累积性。根据加涅的学习层级理论，该生目前只理解了简单的数的概念，没有理解相邻数的概念，未达到辨别学习层级。也没有真正理解运算规则，自然没有达到规则学习和解决问题的学习层级。(1)建议：①利用相关类属学习和总括学习进行知识的扩展。教师可以帮助学生将“8加1\"与其他一系列相关的计算题目联系起来，例如“9加1”“7加1”等。通过这种扩展，学生可以更好地将已有的知识进行归纳总结，理解类似计算的通用方法。②采用多种媒介和多种教学方法展示知识。教师可以利用课件、游戏、数字手表等媒介工具，采用多种教学方法来展示知识。例如，可以将计算题目制成卡片让学生学习，示例学生被教授新单词或概念训练一只狗学习按下一个按钮以获得奖励儿童通过建塔桥的试错过程学习物理原理学生通过观察其他人在跳舞时的步伐和动作学会跳舞或者设计数字媒体互动教学，让学生在趣味和互动中学习和掌握知识。(2）启示：要使教学能积极、有效地展开，教师不能只关注当下的特定任务，更不能简单地重复教学，还应该分析和明确任务目标所需的前提知识、技能及其层级关系，以及学生在学习该任务时实际所处的层级水平。学习是一个过程，需要在多种层面、通过多种方式进行，教育者应具有耐心并用多种方法引导学生，为其提供多视角学习的可能性，让学生在一种充满活力的、融合的教育生态中学习和成长。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b30|46", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 46, "q": "奥苏伯尔将有意义学习分为（）", "opts": ["表征学习、规则学习和命题学习", "表征学习、概念学习和规则学习", "规则学习、概念学习和命题学习", "表征学习、概念学习和命题学习"], "a": 3, "exp": "本题考查奥苏伯尔有意义学习的类型。奥苏伯尔将有意义学习分为表征学习、概念学习和命题学习。表征学习是最低层次的一种学习方式，指学习一个符号或一组符号所代表的事物和意义；概念学习的实质是掌握同类事物的共同关键特征；命题学习是指学习以命题形式表达的观点的新意义。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b30|47", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 47, "q": "加涅认为学习过程的基本模式是（）", "opts": ["构造“完形”的过程", "主动形成认知结构的过程", "对获取的信息进行加工的过程", "形成刺激与反应之间联结的过程"], "a": 2, "exp": "本题考查的知识点是加涅的信息加工理论。加涅基于信息加工理论的有关研究，提出了学习过程的基本模式，具体说明了学习过程中的信息流程。在这个信息已有的经验对现在学习过程的影响，“期望”即动机系统对学习过程的影响，整个学习过程都是在它们的影响下进行的。C选项正确。A选项，构造“完形”的过程是苛勒的观点。B选项，主动形成认知结构是布鲁纳的观点。D选项，形成刺激与反应之间联结的过程是行为主义理论的核心观点。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b30|48", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 48, "q": "心理学家布鲁纳认为，不论教师教的是什么学科，都务必使学生理解该学科的（", "opts": ["目的意义", "方法途径", "基本结构", "发展前景"], "a": 2, "exp": "本题考查认知主义学习理论中布鲁纳的认知结构论。布鲁纳的认知结构学习理论中学习观强调三方面的内容：①教学的目的在于理解学科的基本结构；②提倡发现学习；③掌握学科基本结构的教学原则。他主张学习的目的在于以发现学习的方式，使学科的基本结构转变为学生头脑中的认知结构。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b30|49", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 49, "q": "小学六年级的数学课上，张老师在讲授完税率的含义和算法后，在黑板上写出了一家饭店某个月的营业额，并让同学们计算这家饭店需缴纳的营业税。根据加涅的信息加工理论，学生对饭店营业税的计算环节属于学习阶段中的（）", "opts": ["动机阶段", "领会阶段", "习得阶段", "概括阶段"], "a": 3, "exp": "A选项的动机阶段是整个学习的开始阶段。B选项的领会阶段。有了学习动机的学生，必须注意与学习有关的刺激。当学生把所注意的刺激特征从其他刺激中分化出来时，这些刺激特征就被进行知觉编码，贮存在短时记忆中。最初的注意往往是因刺激的突然变化引起的。为此，教师应采用各种手段来引起学生的注意，如改变讲话的声调、手势动作等。同时，外部刺激的各种特征本身必须是可以被分化和辨别的。学生只有对外部刺激的特征做出选择性知觉后，才能进人其他学习阶段。C选项的习得阶段。在习得阶段，学生对新获得的刺激进行知觉编码后贮存在短时记忆中，然后再把它们进行编码加工后转人长时记忆中。D选项的概括阶段。学生提取信息的过程并不始终是在与最初学习信息时相同的情境一·第二章学习及其理论解释中进行的。同时，教师也总是希望学生能把学到的知识运用于各种类似的情境中去，以达到举一反三的目的。因此，为了促进学习的迁移，教师必须让学生在不同情境中学习，并提供在不同情境中运用提取过程的机会。同时，更为重要的是，要引导学生概括和掌握其中的原理和原则。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b30|50", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 50, "q": "美国教育心理学家布鲁纳主张教育的最终目标是（", "opts": ["促进学生理解学科的基本结构", "促进教师进行更优的教学设计", "促进学生提高学业成绩和技能", "促进学生理解和掌握新知识"], "a": 0, "exp": "本题考查布鲁纳的教学观。布鲁纳强调学习的主动性和认知结构的重要性，他主张教学的最终目标是促进学生对学科基本结构的一般理解。所谓学科的基本结构，是指学科的基本概念、基本原理及其基本态度和基本方法。学生理解了学科的基本结构，就容易掌握整个学科的具体内容，就容易记忆学科知识，就能促进学习迁移。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b30|51", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 51, "q": "物理课上，李老师拿出两个鹤鹑蛋分别放人两个盛有液体的玻璃杯里，结果一个蛋沉了下去，另一个却浮了起来。同学们都非常好奇，热烈地讨论起来。这时李老师在黑板上写下了今天的课题一浮力。根据加涅的信息加工理论，这属于学生学习阶段中的（", "opts": ["动机阶段", "领会阶段", "习得阶段", "概括阶段"], "a": 0, "exp": "本题考查加涅的信息加工理论。加涅在信息加工理论中将学习过程分为八个阶段：动机阶段、领会阶段、习得阶段、保持阶段、回忆阶段、概括阶段、作业阶段和反馈阶段。其中动机阶段是指教学情境中，首先要考虑的是激发学生学习活动的诱因动机，即学生力图达到某种目的的动机。它是借助学生内部产生的心理期望过程而建立起来的。因此，在教学过程中，教师应帮助学生确立学习动机，形成学习期望。题干中李老师运用两个鹤鹑蛋放在液体中出现不同现象的实验巧妙地引发了学生的好奇心和求知欲，使学生展开了热烈地讨论，说明教师激发了学生的学习动机，属于动机阶段，故A选项正确。B选项，领会阶段，即学生接受刺激，把所注意的刺激特征从其他刺激中分化出来，贮存在短时记忆中。C选项，习得阶段，即学生对新获得的刺激进行知觉编码后贮存在短时记忆中，然后再把它们进行编码加工后转人长时记忆中。D选项，概括阶段，即学生将学到的知识运用到各种类似的情境中去，达到举一反三的目的。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b30|52", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 52, "q": "下列不属于认知教学理论基本主张的是（", "opts": ["倡导发现学习法", "强调学科知识结构", "创设真诚与关爱的学习氛围", "以“动机—结构一序列—强化”为教学原则"], "a": 2, "exp": "C选项属于人本主义理论的主张。人本主义的非指导性教学法是美国著名心理学家罗杰斯首倡的，建立在他的人本主义教育价值观的基础上。所谓非指导性教学法，就是创造一种有利于学生学习的气氛，教师（促进者）充分地信任学生，了解学生、尊重学生，从而使学生在整个学习过程中都感到安全与自信，充分显露自己的潜能，朝向自我实现。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b30|53", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 53, "q": "A.强调直观教学", "opts": ["认知结构", "引导学生的发现行为", "激励学生的学习动机", "强调新旧知识的相互联系"], "a": 3, "exp": "组织者一般呈现在新知识的讲授之前，但也可放在新知识学习之后呈现。它既可在抽象和概括水平上高于新学习材料，也可低于原学习材料。组织者可根据它的作用而分为两类：一类是陈述性的组织者，它的作用在于为新知识的学习提供适当的起固定作用的旧知识，提高有关旧知识的可利用性；另一类是比较性组织者，它的作用在于比较新知识与认知结构中有关相似知识的区别和联系，从而增强似是而非的新旧知识之间的可辨别性。由此可知，“组织者”这一技术的实质在于强调新旧知识的相互联系。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b32|54", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 54, "q": "【2009年311真题39】主张“知识是外部现实在人脑中的表征”的学习理论派别是（）", "opts": ["社会建构主义", "激进建构主义", "皮亚杰理论", "信息加工理论"], "a": 3, "exp": "力加涅的信息加工理论主张“知识是外部现实在人脑中的表征”，认为对知识应采用信息加工的方式。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b32|55", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 55, "q": "【2010年311真题36】强调复杂情景和真实学习任务的学习理论派别是（）", "opts": ["联结理论", "认知理论", "建构主义理论", "人本主义理论"], "a": 2, "exp": "建构主义强调复杂情景和真实学习任务。四大常见的学习理论：理论理论主张学习基于联结，通过反复训联结理论练巩固联系容的对象学习是积极的、自我调节的认知理论过程，需要注意控制和元认知的监控过程学习是一种积极的、构建性建构主义的活动，建立在学生已有的理论知识和经验基础上径与场景人本主义学习是全人的发展，需要体验和实践交融理论", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b32|56", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 56, "q": "【2017年311真题36】在有指导的发现学习中，教师提示和指导学生思维以促进学生的理解。这种教学属于（）", "opts": ["程序化教学", "支架式教学", "合作式学习", "讨论式教学"], "a": 1, "exp": "教师提供提示和指导，促进学生的理解，是典型的支架式教学。程序化教学是斯金纳提出的，主要原则有小步子、自定步调、及时反馈、积极反应。常见的教学方法：26S建构主义学习理论教育实践学习角色学习者应该是被动接收内重视对基础知识的灌输和强化学习者是知识与技能的主注重学生的个体差异和学人，需要了解自己的学习习策略的培养学习者是知识的建造者，强调启发式教学和学生自主需要建立个体化的学习路学习，提倡基于问题的学习基于个人中心的学习.注重学习者是人类发展的核学生情感与自我认知，反对心，需要受到尊重与关注标准化教育教学方法优点定义教学过程逻辑清晰易程序化以一系列事先规定好的步骤于掌握，有效避免遗漏教学和过程来教授知识或技能或错误提供特定的学习支架，帮助有助于学生进行自主支架式探究，帮助师生合作完学生在新领域中获得知识教学并解决问题成复杂任务提高学习效果和学习合作式学生一起加人小组，分工合质量，增强团队合作和学习作处理任务并分享学习成果沟通能力讨论式教师引导学生讨论特定的提高学生思维的深度教学问题、观点或文章内容和广度，激发学生兴趣", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b32|57", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 57, "q": "【2017年311真题37】学习需在别人的帮助下，在真实和现实的情境中发生。这种建构主义的主张属于(", "opts": ["个人建构主义", "认知建构主义", "心理建构主义", "社会建构主义"], "a": 3, "exp": "社会建构主义强调在他人帮助下或采用合作学习的方式进行学习。根据题干，此题应选D选项。常见的建构主义类型：卖美注久建构主义类型学习者是知识的建构者和主人，建个人建构主义立在已有知识和经验的基础上进行学习，注重个体差异和个性差异学习者利用认知策略建立知识结认知建构主义构，注重知识的意义与价值，重视元认知过程的控制和监控学习过程中的情感和情绪对于知识建构和发展有着重要影响，强调心理建构主义关注情感和情绪因素在知识构建和认知过程中的作用学习是一种社会化过程，语言、交流和社会文化环境影咱着知识建社会建构主义构和认知过程，注重多元文化背景的融人和社会意义价值社会建构主义学习理论认为，学习是一个文化参与的过程，学习者通过参", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b32|58", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 58, "q": "【2019年311真题9】小组合作学习不同于能力分组教学，它推崇不同背景、能力及倾）向的学生共同学习。为其提供有力支持的理论是（", "opts": ["行为主义学习理论", "认知主义学习理论", "人本主义学习理论", "社会建构主义学习理论"], "a": 3, "exp": "与到某个共同体的实践活动中，建构有关的知识。题干中教师变化不同的情境，促进学生对浮力的理解，使用了随机通达教", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b32|59", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 59, "q": "【2021年311真题37】为了让学生理解浮力的原理，教师先要求学生把一个土豆放进盛着水的容器里，土豆沉到水底，然后让学生不断往水里放盐，直到土豆浮起来；随后又往容器里加水，直到土豆又沉到水底；如此反复多次。在这一教学案例中，教师使用）了（", "opts": ["支架式教学", "认知学徒制", "随机通达教学", "互惠式教学"], "a": 2, "exp": "学。随机通达教学要求在教学中促进学生在多个情境中从多个角度对问题进行建构。常见教学方式的定义及优缺点：，第二章学习及其理论解释缺点学习者容易出现机械化、缺乏创造性的特点，可能无法适应应用环境的复杂性可能会限制学生个体差异和创造性的发挥学习成果可能受到一些小组的依赖或控制，对于细节准确性的考虑会被忽略学生可能会占据过多的时间，出现谈话不够深人、效果不显著等情况理论重点实践策略知识的本质、个体差个性化学习路径、经异、建构过程的个体验分享、自我评价式反思知识建构的基本规律、反思概念、合作学习、问题导向的学习元认知机制的调整情感与学习、社会环激活情感体验、情感境、情感状况的识别调节、自我控制技能和管理的培养语言、社会文化和社合作学习、社区学会环境的影响，个人习、项目制教学主义和共同体主义教学方式定义提供一定的学习支持和指支架式教学导，帮助学生掌握新知识和解决问题师生共同参与学习过程，认知学徒制激发学生的自主性，强调认知转移能力的培养学生在探究问题的过程随机通达中，不断通过自主学习和教学反思获取知识和技能教师和学生交流合作，以互惠式教学协作和互助为核心进行教学活动", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b32|60", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 60, "q": "【2023年311真题36】认知负荷理论强调，教学设计要注重减少学生不必要的认知负荷。这里的认知负荷主要发生在（）", "opts": ["工作记忆中", "长时记忆中", "感觉登记中", "情景记忆中"], "a": 0, "exp": "认知负荷理论假设人类的认知结构由工作记忆和长时记忆组成，教学的主要功能是在长时记忆中存储信息。知识以图式的形式存储于长时记忆中。图式根据信息元素的使用方式来组织信息，它提供知识组织和存储的机制，可以减少工作记忆负荷。因此，认知负荷理论要减少的是工作记忆的负担，A选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b32|61", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 61, "q": "【2025年311真题35】对于教学、人本主义学习论和建构主义学习论都强调（", "opts": ["文化工具的使用", "以学生为中心", "把自我实现作为教育目标", "接受学习"], "a": 1, "exp": "人本主义主张教育应关注学生情感与自我实现，反对教师主导的灌输式教学；建构主义认为学习是学生主动建构知识的过程，而非被动接受。两者均强调教学需围绕学生展开，核心是以学生为中心。B选项正确。A选项，“文化工具的使用”是维果茨基社会建构主义的观点，侧重借助语言、符号等工具促进学习，并非人本主义与建构主义的共同主张。C选项，“把自我实现作为教育目标”是人本主义的核心目标，建构主义更关注学生知识建构能力的培养，不将自我实现作为核心目标。D选项，“接受学习”是奥苏伯尔认知主义的观点。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b34|62", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 62, "q": "某老师在做经验交流时，强调学生学习主动性的重要性、合作学习的重要性以及教师对学习情境创设的重要性。这位老师可能更支持（", "opts": ["联结学习理论", "认知学习理论", "人本主义学习理论", "建构主义学习理论"], "a": 3, "exp": "本题考查的知识点是一般学习理论中的建构主义学习理论的基本观点。建构主义学习理论是新课程改革的理论基础之一，强调学习的主动建构性、社会互动性和情境性，故D选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b34|63", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 63, "q": "教师与学生共同完成学习活动，并为学生提供外部支持，帮助学生完成他们无法自己独立完成的任务，这种教学方式属于（）", "opts": ["支架式教学", "探究式教学", "情境性教学", "感染性教学"], "a": 0, "exp": "本题考查的知识点是支架式教学的概念。支架式教学首先强调在教师指导的情况下学生的发展活动；其次，教师指导成分将逐渐减少，最终要使学生达到独立发现的水平，将监控学习和探索的责任由教师向学生转移。题干中，教师与学生共同学习，缺点优点可能不够适应复杂和多有助于学生建立自信，激变的学习环境，学生可能发学生探究和发现新知识会出现对学习指导的依的兴趣和潜力赖性有助于学生形成对知识的需要较长的时间才能看深层理解和批判性思维，到学习成果，需要较好的强化学生的元认知能力学习环境和学习氛围学生需要很强的自我管有助于学生通过自主学习理和控制能力，学习成果和探究掌握新知识和技能难以量化需要学生与教师有较好有助于培养学生的合作精的沟通和信任基础，需要神和团队协作能力，提高教师具有较好的教学设知识的分享欲和凝聚力计和运作能力并为学生提供支持，帮助他们独立完成任务，符合支架式教学的特点。要观点：①学习具有主动建构性。学习不是由教师向学生传递知识的过程，学习者不是被动的信息吸收者，而是主动的信息建构者。②学习具有社会互动性。学习是通过对某种社会文化的参与而内化相关的知识和技能、掌握有关工具的过程，这一过程常常通过一个学习共同体的合作互动来完成。③学习具有情境性。建构主义者强调学习、知识和技能的情境性。知识是不可能脱离活动情境而抽象存在的，学习应该与情境化的社会实践活动结合起来。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b36|64", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 64, "q": "强调教学要完全以儿童为中心的教育理论偏向于采用的教学模式为（", "opts": ["掌握教学模式", "非指导性教学模式", "范例教学模式", "逆向教学模式"], "a": 1, "exp": "根据题意，强调以儿童为中心的教育理论，会偏向于采用让学生主动学B选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b36|65", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 65, "q": "以下不属于人本主义学习理论观点的是（）", "opts": ["教学目标中注重情感与认知的统一", "教学过程中强调学生的中心地位", "教学内容以知识为主", "教育内容要针对学生的生活需求"], "a": 2, "exp": "本题考查人本主义的学习理论。人本主义的学习理论认为,教育应重视知识和情感的培养，培养学生的生活能力。“教学内容以知识为主”不属于人本主义学习理论的观点，故选C选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-02|b36|66", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-02", "chName": "", "sec": "基础练习", "no": 66, "q": "在实际的教育活动中，强调学生中心忽视了教师的指导作用。这是以下哪个学习理论的明显不足(", "opts": ["观察学习理论", "人本主义学习理论", "行为主义学习理论", "掌握学习理论"], "a": 1, "exp": "，人本主义学习理论倡导非指导性教学，在实施过程中，过分强调以学生为中心，忽视了教师的指导作用，这是人本主义存在的明显不足。C选项，行为主义学习理论强调的是行为和反应之间的联结，强调强化的重要性。D选项，掌握学习理论认为只要给学生足够的时间，学生就可以掌握绝大多数的知识。A、C、D选项均未强调以学生为中心。后续关注公众号【研大］永久微信1931637888一·第二章学习及其理论篇释", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b39|1", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 1, "q": "【2007年311真题39】“知之者不如好之者，好之者不如乐之者。”这一论述强调的学习动机类型是(", "opts": ["内部动机", "外部动机", "社会交往动机", "自我提高动机"], "a": 0, "exp": "A选项“内部动机”，指为了学习而学习，为了求知去学习。B选项“外部动机”，表现为个体因外部因素如奖励、惩罚、压力等进行学习。C选项“社会交往动机”表现为个体想在符合群体要求的情况下得到发展，否则就会感到孤独、别扭或焦虑。D选项“自我提高动机”可以理解为自我提高内驱力，是为了提高个体的社会地位。题干表达的是“对于学习，了解怎么学习的人，不如喜爱学习的人；喜爱学习的人，又不如以学习为乐的人”，这强调的是学生学习内在动机的重要性。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b41|2", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 2, "q": "某小学低年级教师喜欢用“真”“真行”表扬学生，学生往往得到激励。但随着年龄的增加，学生对其表扬不再感兴趣。这一现象说明（", "opts": ["随着年龄的增加，学生对语言激励不感兴趣", "随着年龄的增加，学生对物质激励更感兴趣", "随着年龄的增加，学生的认知内驱力有所减弱", "随着年龄的增加，学生的附属内驱力有所减弱"], "a": 3, "exp": "本题考查的知识点是奥苏伯尔成就动机的分类。奥苏伯尔等人认为成就动机包括三方面的内驱力：认知内驱力、自我提高内驱力和附属内驱力。附属内驱力是指个人为了保持长者们或权威们的赞许或认可，而表现出来的一种把学习或工作做好的动力。随着儿童年龄的增长和独立性的增强，附属内驱力不仅在强度上有所减弱，而且附属对象也从家长和教师转移到同伴身上。故D选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b41|3", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 3, "q": "杨艺最近对食物吃到胃里是如何消化、转化为身体所需养料并被身体吸收的过程十分感兴趣。因此她在生物课上十分认真，并感受到生物老师的表扬。之后一段时间，杨艺对生物课学习的积极性更高了。根据奥苏伯尔的分类，杨艺的学习动机是（", "opts": ["内部动机，附属内驱力", "认知内驱力：附属内驱力", "内部动机，自我提高内驱力", "认知内驱力、自我提高内驱力"], "a": 1, "exp": "题干中，杨艺渴望掌握与消化吸收相关的生物学知识，这种学习动机属于认知内驱力；之后，她因渴望受到生物老师的表扬而学习，这种学习动机属于附属内驱力。杨艺因知识本身而引起的学习动机属于内部动机，但该动机不属于奥苏伯尔的学习动机分类。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b42|4", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 4, "q": "【2008年311真题44】以掌握为目标定向的学生倾向于将学业成败归因于（", "opts": ["能力", "努力", "运气", "任务难度"], "a": 1, "exp": "目标定向包括掌握目标定向和表现目标定向两类。掌握目标定向以获取知识为主，主要依靠内部动机，相信努力带来成功。表现目标定向以证明自己为主，主要依靠外部动机，相信能力是重要的。目标定向理论又称成就目标理论，是在德维克的能力理论基础上提出的。德维克认为，人们对于能力有不同的内隐观念：一是能力实体观，认为能力是稳定的，是不可改变的特质；二是能力增长观，认为能力是不稳定的，可以随着知识的学习和技能的培养而提高。持能力实体观的学生倾向于建立表现目标，从而避免被人看不起；持能力增长观的学生则更多设置掌握目标，并寻求那些真正锻炼自己的能力、提高自己技能的任务。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b42|5", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 5, "q": "【2011年311真题37】认为学业求助是缺乏能力的表现，是对自我价值构成威胁的学）生，其成就目标定向类型是（", "opts": ["掌握目标", "学习目标", "任务目标", "表现目标"], "a": 3, "exp": "设置表现目标的学生会更在乎自我价值，认为向他人求助等于承认自己的能力不足，无法表现自我。目标定向理论：名称学习是为了取得成就，展示自己。如果失败，容易产生一种无助表现目标（也叫作成就目标）学习是为了掌握真正的知识，不畏俱失败，更愿意寻找方法。归因掌握目标（也叫作任务目标）", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b42|6", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 6, "q": "【2012年311真题38】某学生因对“必须坚持每天一定量运动达半年以上”的要求感到自已落实困难而放弃了瘦身计划。根据班杜拉的理论，这表明其对瘦身的（）", "opts": ["结果期望低", "结果期望高", "效能期望低", "效能期望高"], "a": 2, "exp": "自我效能感是指个体对自己能否做成某一件事的期待。学生认为自己的瘦身计划难以落实进而放弃了，这属于自我效能感低的表现。低，但这个因素与本题中学生放弃瘦身计划的原因不相符。学生并没有对瘦身的效果持悲观态度或缺乏期望，而是认为自己无法坚持长期的运动。B选项“结果期望高”指的是个体对任务完成后可获得奖励或利益的预期程度较高，既与题干不相关，也与学生选择放弃瘦身计划不一致。学习动机的主要理论特点感。归因易从外部原因着手，在意外界的看法更多地考虑自己的学习方法和努力程度，更多地关注自身计划恰恰表明了他对完成任务的信心不足，因此D选项也不符合题意。自我效能感是班杜拉提出来的，是指人们对自己能否成功地进行某一行为的主观判断。影响自我效能感的因素有直接经验、替代经验、言语说服、情绪唤起。提高学生自我效能感的方法有：传授具体的学习策略；指导学生制定相应的学习目标；考虑学生对学习内容的真实掌握水平；将策略训练同学习目标相结合，及时反馈；确保不要过度激起学生的情绪；为学生树立成人或同伴的正面榜样。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b42|7", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 7, "q": "【2013年311真题34】根据马斯洛的需要层次理论，下列选项属于缺失性需要的是）", "opts": ["自我实现的需要", "自尊的需要", "认知的需要", "审美的需要"], "a": 1, "exp": "马斯洛的需要层次理论包括：生理需要、安全需要、归属和爱的需要、尊重的需要、求知与理解的需要、美的需要、自我实现的需要。前四种是缺失性需要，后三种是成长需要。在学校中的学生，缺失性需要表现得更为明显。马斯洛的需要层次理论表明，学生缺乏学习动机，在一定程度上可能是某种缺失性需要没有得到充分满足而引起的。例如，家境贫寒使得温饱不能满足；父母离异让孩子丧失归属感并缺乏爱等。因此，教师不仅要在学业方面主动帮助学生，也要在生活与情感方面积极地关心学生、爱护学生，让学生感受到教师对他们的尊重和爱护。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b42|8", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 8, "q": "【2014年311真题38】某学生将自己某学科的学业失败归结为“自己不是学这科的料”。他的这种归因属于（）", "opts": ["内部、稳定性的归因", "外部、稳定性的归因", "内部、不稳定的归因", "外部、不稳定的归因"], "a": 0, "exp": "儿童早期，附属内驱力最为突出；少年时期，附属内驱力的强度减弱，更加关注同伴的赞许；青年时期，认知内驱力和自我提高内驱力成为主要驱力。附属内驱力指学生想要得到家长、教师等的认可；自我提高内驱力是学生想要提高自身的地位；认知内驱力是学生想要学习知识。人们倾向于将活动成败的原因归结于六个因素：能力高低、努力程度、任务难度、运气好坏、身心状态、外界环境；三个维度：内部与外部、稳定与不稳定、可控与不可控。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b42|9", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 9, "q": "【2016年311真题35】丽丽是个害羞的女生，即将参加演讲比赛。如果她是内控型的人，她很可能将演讲的成功归因于（", "opts": ["自己具有这个能力", "认真的准备", "运气好", "任务要求简单"], "a": 1, "exp": "运气、任务难度属于外部因素，能力和努力属于内部因素。此题还有一个解题的关键在于“害羞”，一个害羞的人是很难直接在他人面前承认自己的成功是来自能力的，更偏向于认为成功是因为自己认真地准备。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b42|10", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 10, "q": "【2017年311真题38】“对做好一份工作的奖励，就是这份工作已圆满完成。”这句话隐含着（（）", "opts": ["负强化", "替代强化", "内在强化", "外在强化"], "a": 2, "exp": "工作圆满完成就是对这份工作的奖励属于典型的内在强化。内在强化强调事情本身的价值，外在强化一般强调金钱、其他奖励等。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b42|11", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 11, "q": "【2018年311真题36】有的学生愿意为他所喜欢的老师努力学习，而面对不喜欢的老师则不愿意努力学习。此时影响学习的主要因素是（）", "opts": ["成就动机", "认知动机", "交往动机", "自我提高动机"], "a": 2, "exp": "交往动机是指个体由于需要与他人建立、维护和发展关系而产生的内在动力，例如在学校里和同学、老师相处，企业中的同事和领导相处等。学生为了自己喜欢的老师努力，这属于交往动机。成就动机是为了获得成功；认知动机是为了学习知识；自我提高动机是为了获得地位和自尊心。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}]);
